/**
 * One row of S-17's grid. **Not `Ticket`** — the list has never returned
that shape, and this schema is the contract catching up with A-053
rather than a change to the server.

A-053 chose flat ids over nested `project`, `client` and `assignee`
objects for a stated reason: a list is where nesting costs most, since
one row becomes one lookup per row and S-17 renders fifty of them. The
masters are small and already cached client-side, which is the pattern
`moduleId` documents on `Ticket` itself — "resolve the name through
`GET /masters/modules` rather than expecting it inline".

**Declaring `Ticket` here was a real defect, not a harmless
imprecision.** The generated client typed the grid against nested
objects the server never sends, so the ID column rendered blank, every
row read "Unassigned", and Project and Client showed an em dash — on a
screen whose data was entirely present. Every field the API does send
rendered correctly, which is what made it look like a data problem
rather than a contract one.

It also omits the heavy fields deliberately: description and
steps-to-generate belong to the detail page, and shipping sanitised HTML
per row to render a title would make the list slower than the waterfall
A-052 exists to remove.

 */
export interface TicketSummary {
  /** The surrogate key. Present because bulk actions address rows by it; every user-facing link uses `ticketCode`.
 */
  id: number;
  ticketCode: TicketId;
  title: string;
  projectId: number;
  clientId?: TicketSummaryClientId;
  isClientRaised?: boolean;
  taskTypeId?: TicketSummaryTaskTypeId;
  level: Level;
  originalLevel?: Level;
  status: StatusCode;
  currentStage?: TicketSummaryCurrentStage;
  /** Null means unassigned, which the grid renders as such. */
  assignedTo?: TicketSummaryAssignedTo;
  reportedBy?: TicketSummaryReportedBy;
  cycleNo: number;
  iterationNo?: number;
  reopenCount?: number;
  isReopened?: boolean;
  dateReported?: string;
  plannedCloseDate?: TicketSummaryPlannedCloseDate;
  actualCloseDate?: TicketSummaryActualCloseDate;
  isDelayed?: boolean;
  delayedSince?: TicketSummaryDelayedSince;
  estimatedEffortHrs?: TicketSummaryEstimatedEffortHrs;
  totalEffortHrs?: TicketSummaryTotalEffortHrs;
  commentCount?: number;
  attachmentCount?: number;
  createdAt?: string;
}
